INSERT INTO character_translations(character_id,locale,name,summary,status,aliases,detail,motivation)
SELECT c.id,v.locale::locale_code,v.name,v.summary,'published',v.aliases,v.detail,v.motivation FROM characters c JOIN (VALUES
('noah','zh-CN','挪亚','洪水叙事的中心人物。',ARRAY[]::text[],'起源叙事段落不提供可换算的年代，本条目不放置在历史轴上。','在灾难叙事中保全家族与生物。'),
('noah','en','Noah','The central figure of the flood narrative.',ARRAY[]::text[],'The origin-narrative section supplies no convertible chronology, so this entry is not placed on the historical axis.','To preserve household and living creatures through a catastrophe narrative.'),
('lot','zh-CN','罗得','亚伯拉罕的侄子，与所多玛叙事相关。',ARRAY[]::text[],'其迁徙选择与亚伯拉罕形成对照。','为家族寻找更肥沃的定居地。'),
('lot','en','Lot','Abraham’s nephew, tied to the Sodom narrative.',ARRAY[]::text[],'His settlement choice is set in contrast with Abraham’s.','To find more fertile land for his household.'),
('hagar','zh-CN','夏甲','撒拉的使女，以实玛利的母亲。',ARRAY[]::text[],'其叙事线索处理家族内部的地位冲突与旷野生存。','在被排除的处境中保全孩子。'),
('hagar','en','Hagar','Sarah’s servant and the mother of Ishmael.',ARRAY[]::text[],'Her thread handles status conflict inside the household and survival in the wilderness.','To keep her child alive after exclusion.'),
('ishmael','zh-CN','以实玛利','亚伯拉罕与夏甲之子。',ARRAY[]::text[],'代表族长家族的另一条分支。','在主线之外建立自己的族群。'),
('ishmael','en','Ishmael','The son of Abraham and Hagar.',ARRAY[]::text[],'He represents the other branch of the patriarchal household.','To establish his own people outside the main line.'),
('rebekah','zh-CN','利百加','以撒之妻，雅各与以扫之母。',ARRAY[]::text[],'她在继承权叙事中主动介入。','为偏爱的儿子争取家族祝福。'),
('rebekah','en','Rebekah','Isaac’s wife and mother of Jacob and Esau.',ARRAY[]::text[],'She intervenes actively in the inheritance narrative.','To secure the family blessing for her preferred son.'),
('esau','zh-CN','以扫','以撒长子，与雅各的对立与和解线索。',ARRAY['以东']::text[],'兄弟冲突与最终和解构成完整弧线。','取回被夺走的长子名分。'),
('esau','en','Esau','Isaac’s elder son; the rivalry-and-reconciliation thread with Jacob.',ARRAY['Edom']::text[],'The sibling conflict and eventual reconciliation form a complete arc.','To reclaim the birthright taken from him.'),
('rachel','zh-CN','拉结','雅各所爱的妻子，约瑟与便雅悯之母。',ARRAY[]::text[],'她的叙事贯穿劳动契约、生育与迁徙。','在多妻家庭中确立自己与孩子的位置。'),
('rachel','en','Rachel','Jacob’s beloved wife and mother of Joseph and Benjamin.',ARRAY[]::text[],'Her thread runs through labour contracts, childbearing, and migration.','To secure a place for herself and her children in a polygamous household.'),
('leah','zh-CN','利亚','雅各的第一位妻子，多个支派的母亲。',ARRAY[]::text[],'她的后代构成后来的主要支派。','在不被偏爱的处境中获得承认。'),
('leah','en','Leah','Jacob’s first wife and mother of several tribes.',ARRAY[]::text[],'Her descendants form several of the later tribes.','To gain recognition in a household where she is not preferred.'),
('joseph-son-of-jacob','zh-CN','约瑟','从被卖到埃及执政的叙事主角。',ARRAY[]::text[],'其叙事把族长家族带入埃及，接上出埃及叙事。','在异地重建地位并保全家族。'),
('joseph-son-of-jacob','en','Joseph','The protagonist of the sold-into-Egypt and rise-to-office narrative.',ARRAY[]::text[],'His thread carries the patriarchal household into Egypt and sets up the Exodus narrative.','To rebuild standing abroad and preserve his family.'),
('judah-son-of-jacob','zh-CN','犹大','雅各之子，后来犹大支派的名祖。',ARRAY[]::text[],'在约瑟叙事与后来的王室谱系中都出现。','在兄弟冲突中承担调解与担保。'),
('judah-son-of-jacob','en','Judah','A son of Jacob and eponym of the later tribe of Judah.',ARRAY[]::text[],'He appears in the Joseph narrative and in later royal genealogy.','To mediate and stand surety amid sibling conflict.'),
('benjamin','zh-CN','便雅悯','雅各最小的儿子。',ARRAY[]::text[],'在约瑟叙事的重逢段落中处于关键位置。','在家族叙事中作为最受保护的一员。'),
('benjamin','en','Benjamin','Jacob’s youngest son.',ARRAY[]::text[],'He occupies the pivotal position in the reunion section of the Joseph narrative.','To remain the most protected member of the household.'),
('miriam','zh-CN','米利暗','摩西与亚伦的姐妹，旷野叙事中的先知人物。',ARRAY[]::text[],'其叙事包含领唱、异议与被隔离等段落。','在群体中争取自己的发言位置。'),
('miriam','en','Miriam','Sister of Moses and Aaron and a prophetic figure in the wilderness narrative.',ARRAY[]::text[],'Her thread includes leading song, dissent, and a period of exclusion.','To claim a speaking role within the community.'),
('jethro','zh-CN','叶忒罗','摩西的岳父，米甸祭司。',ARRAY['流珥']::text[],'提出分层审判制度的建议。','以外部视角为新兴群体提供治理建议。'),
('jethro','en','Jethro','Moses’ father-in-law and a Midianite priest.',ARRAY['Reuel']::text[],'He proposes the tiered system for hearing disputes.','To offer governance advice to a new community from outside it.'),
('pharaoh-of-the-exodus','zh-CN','出埃及叙事中的法老','出埃及叙事中的埃及统治者。',ARRAY[]::text[],'文本未给出名字，与具体历史法老的对应无学界共识，因此不设年代。','维持既有劳动与统治秩序。'),
('pharaoh-of-the-exodus','en','Pharaoh of the Exodus narrative','The Egyptian ruler in the Exodus narrative.',ARRAY[]::text[],'The text gives no name and no scholarly consensus links him to a specific pharaoh, so no years are recorded.','To maintain the existing order of labour and rule.'),
('joshua','zh-CN','约书亚','摩西之后带领群体进入迦南的领袖。',ARRAY[]::text[],'连接旷野叙事与定居叙事。','完成迁徙并建立定居秩序。'),
('joshua','en','Joshua','The leader who brings the community into Canaan after Moses.',ARRAY[]::text[],'He links the wilderness narrative to the settlement narrative.','To complete the migration and establish a settled order.'),
('caleb','zh-CN','迦勒','探子叙事中的少数意见者。',ARRAY[]::text[],'与约书亚一同代表不同评估。','坚持自己对形势的判断。'),
('caleb','en','Caleb','The minority voice in the scouting narrative.',ARRAY[]::text[],'With Joshua he represents the dissenting assessment.','To hold to his own reading of the situation.'),
('rahab','zh-CN','喇合','耶利哥叙事中协助探子的当地人。',ARRAY[]::text[],'外来者与本地人身份在此交叉。','为自己与家人换取生存保障。'),
('rahab','en','Rahab','The local resident who shelters the scouts in the Jericho narrative.',ARRAY[]::text[],'Insider and outsider identities cross in this thread.','To secure survival for herself and her family.'),
('deborah','zh-CN','底波拉','士师时代的女性领袖与先知。',ARRAY[]::text[],'兼具裁决与军事动员两种角色。','在缺乏中央权力时组织抵抗。'),
('deborah','en','Deborah','A woman leader and prophet of the judges era.',ARRAY[]::text[],'She combines the roles of adjudicator and military organiser.','To organise resistance where no central authority exists.'),
('barak','zh-CN','巴拉','与底波拉合作的军事领袖。',ARRAY[]::text[],'其犹豫使叙事把功劳转向他人。','在没有把握时寻求支持。'),
('barak','en','Barak','The military leader who works with Deborah.',ARRAY[]::text[],'His hesitation causes the narrative to shift the credit elsewhere.','To seek backing before acting without certainty.'),
('gideon','zh-CN','基甸','以小规模行动著称的士师。',ARRAY['耶路巴力']::text[],'叙事强调反复确认与人数削减。','在自我怀疑中承担领导责任。'),
('gideon','en','Gideon','A judge known for a deliberately small-scale action.',ARRAY['Jerubbaal']::text[],'The narrative stresses repeated confirmation and the reduction of numbers.','To take on leadership despite self-doubt.'),
('samson','zh-CN','参孙','士师叙事中力量与失控并存的人物。',ARRAY[]::text[],'个人冲动与群体冲突交织。','以个人方式回应压迫。'),
('samson','en','Samson','A judge in whom strength and loss of control coexist.',ARRAY[]::text[],'Personal impulse and collective conflict are interwoven.','To answer oppression on his own terms.'),
('delilah','zh-CN','大利拉','参孙叙事中的对立人物。',ARRAY[]::text[],'其动机在文本中与外部压力和报酬相关。','在两方压力之间选择自身利益。'),
('delilah','en','Delilah','The antagonist of the Samson narrative.',ARRAY[]::text[],'The text ties her motive to external pressure and payment.','To choose her own interest between two pressures.'),
('ruth','zh-CN','路得','从摩押来到伯利恒的外族女性。',ARRAY[]::text[],'其谱系被后来的王室叙事引用。','以忠诚选择重建生活。'),
('ruth','en','Ruth','A Moabite woman who comes to Bethlehem.',ARRAY[]::text[],'Her genealogy is cited by the later royal narrative.','To rebuild a life through a chosen loyalty.'),
('boaz','zh-CN','波阿斯','伯利恒的地主，路得叙事的另一方。',ARRAY[]::text[],'叙事围绕赎回制度展开。','在既定习俗中承担亲属责任。'),
('boaz','en','Boaz','A Bethlehem landowner and the counterpart in the Ruth narrative.',ARRAY[]::text[],'The narrative turns on the redemption custom.','To take up a kinsman’s obligation within established custom.'),
('samuel','zh-CN','撒母耳','连接士师时代与王国时代的先知。',ARRAY[]::text[],'先后膏立扫罗与大卫。','在制度转型中维持判断权威。'),
('samuel','en','Samuel','The prophet who links the judges era to the monarchy.',ARRAY[]::text[],'He anoints first Saul and then David.','To retain authority of judgement across an institutional change.'),
('saul','zh-CN','扫罗','第一位王，与大卫的对立线索。',ARRAY[]::text[],'其叙事从被拣选走向失势。','保住王位与家族继承。'),
('saul','en','Saul','The first king and David’s antagonist thread.',ARRAY[]::text[],'His arc runs from being chosen to losing standing.','To hold the throne and his family’s succession.'),
('jonathan','zh-CN','约拿单','扫罗之子，与大卫的盟约关系。',ARRAY[]::text[],'在父亲与朋友之间的张力构成主要冲突。','在忠诚冲突中保全友谊。'),
('jonathan','en','Jonathan','Saul’s son, bound to David by covenant.',ARRAY[]::text[],'The tension between father and friend is his central conflict.','To preserve a friendship against a conflict of loyalties.'),
('goliath','zh-CN','歌利亚','以拉谷对峙叙事中的非利士战士。',ARRAY[]::text[],'作为体量与技巧对比的叙事装置。','以个人挑战决定群体胜负。'),
('goliath','en','Goliath','The Philistine champion in the Valley of Elah narrative.',ARRAY[]::text[],'He functions as the narrative device contrasting size with skill.','To settle a collective conflict by single combat.'),
('abigail','zh-CN','亚比该','以谈判化解冲突的人物。',ARRAY[]::text[],'其介入避免了一次报复行动。','以主动交涉保全家族。'),
('abigail','en','Abigail','A figure who defuses a conflict by negotiation.',ARRAY[]::text[],'Her intervention prevents a reprisal.','To protect her household by taking the initiative.'),
('bathsheba','zh-CN','拔示巴','大卫叙事中的关键人物，所罗门之母。',ARRAY[]::text[],'其叙事包含权力不对等与后来的继承干预。','在宫廷结构中确保儿子的继承。'),
('bathsheba','en','Bathsheba','A pivotal figure in the David narrative and Solomon’s mother.',ARRAY[]::text[],'Her thread covers an asymmetry of power and a later succession intervention.','To secure her son’s succession within the court structure.'),
('absalom','zh-CN','押沙龙','大卫之子，发动叛乱的人物。',ARRAY[]::text[],'家族内部冲突升级为政治危机。','取代父亲取得王权。'),
('absalom','en','Absalom','David’s son, who mounts a revolt.',ARRAY[]::text[],'A household conflict escalates into a political crisis.','To take the throne in his father’s place.'),
('nathan','zh-CN','拿单','宫廷先知，对大卫提出指控。',ARRAY[]::text[],'以叙事比喻方式进行政治批评。','在权力面前维持批评职能。'),
('nathan','en','Nathan','The court prophet who confronts David.',ARRAY[]::text[],'He delivers political criticism through a narrative parable.','To keep a critical function alive in the presence of power.'),
('joab','zh-CN','约押','大卫的军队统帅。',ARRAY[]::text[],'多次以强硬手段处理政治问题。','以军事效率维持政权稳定。'),
('joab','en','Joab','David’s army commander.',ARRAY[]::text[],'He repeatedly resolves political problems by force.','To keep the regime stable through military efficiency.'),
('rehoboam','zh-CN','罗波安','所罗门之子，王国分裂时的南方君主。',ARRAY[]::text[],'其决策成为分裂叙事的直接触发点。','维持父辈的税役体制。'),
('rehoboam','en','Rehoboam','Solomon’s son and the southern king at the division of the kingdom.',ARRAY[]::text[],'His decision is the immediate trigger of the division narrative.','To maintain his father’s system of levy and labour.'),
('jeroboam','zh-CN','耶罗波安','北国以色列的首位君主。',ARRAY[]::text[],'其建立的祭祀安排在后续叙事中被反复评价。','为新政权建立独立的宗教中心。'),
('jeroboam','en','Jeroboam','The first king of the northern kingdom of Israel.',ARRAY[]::text[],'The cult arrangements he establishes are repeatedly assessed in later narrative.','To give the new state its own religious centre.'),
('elijah','zh-CN','以利亚','北国时期的先知，与王室对抗。',ARRAY[]::text[],'其叙事包含公开对峙与旷野退隐两个方向。','在王权之外维持独立的宗教立场。'),
('elijah','en','Elijah','A prophet of the northern kingdom in conflict with the crown.',ARRAY[]::text[],'His thread runs in two directions: public confrontation and wilderness withdrawal.','To hold an independent religious position outside royal power.'),
('elisha','zh-CN','以利沙','以利亚的继任者。',ARRAY[]::text[],'叙事重心从对抗转向地方性事件。','延续前任的职分并贴近民间。'),
('elisha','en','Elisha','Elijah’s successor.',ARRAY[]::text[],'The narrative focus shifts from confrontation to local episodes.','To continue his predecessor’s role closer to ordinary life.'),
('ahab','zh-CN','亚哈','北国君主，外部铭文亦有记载。',ARRAY[]::text[],'库尔赫石碑等外部材料提到同名君主，是少见的对照点。','以联姻与工程巩固政权。'),
('ahab','en','Ahab','A northern king also named in external inscriptions.',ARRAY[]::text[],'External material such as the Kurkh monolith names a king of this name, a rare point of comparison.','To consolidate power through marriage alliance and building works.'),
('jezebel','zh-CN','耶洗别','亚哈的王后，叙事中的主要对立者。',ARRAY[]::text[],'外来王室背景与本地宗教冲突交织。','把母国的宗教与政治模式带入北国。'),
('jezebel','en','Jezebel','Ahab’s queen and a principal antagonist in the narrative.',ARRAY[]::text[],'A foreign royal background is interwoven with local religious conflict.','To bring her homeland’s religious and political model into the northern kingdom.'),
('hezekiah','zh-CN','希西家','面对亚述围城的犹大君主。',ARRAY[]::text[],'西拿基立棱柱与水道工程为其提供外部对照。','在强敌压境下保住耶路撒冷。'),
('hezekiah','en','Hezekiah','The king of Judah facing the Assyrian siege.',ARRAY[]::text[],'The Sennacherib prism and the water tunnel provide external comparison.','To hold Jerusalem against a stronger power.'),
('isaiah','zh-CN','以赛亚','与希西家同期的先知人物。',ARRAY[]::text[],'文本长期被认为出自多个时期，本条目只涉及叙事段落。','在国际危机中提供政治宗教判断。'),
('isaiah','en','Isaiah','A prophetic figure contemporary with Hezekiah.',ARRAY[]::text[],'The book is long held to span several periods; this entry covers only the narrative sections.','To offer political and religious judgement during an international crisis.'),
('jeremiah','zh-CN','耶利米','耶路撒冷陷落前后的先知。',ARRAY[]::text[],'叙事包含被囚、被带往埃及等段落。','在崩解过程中坚持不受欢迎的判断。'),
('jeremiah','en','Jeremiah','A prophet before and after the fall of Jerusalem.',ARRAY[]::text[],'His thread includes imprisonment and being taken to Egypt.','To hold to an unwelcome judgement during a collapse.'),
('ezekiel','zh-CN','以西结','被掳群体中的先知。',ARRAY[]::text[],'叙事位置在巴比伦而非耶路撒冷。','为流散群体重建意义框架。'),
('ezekiel','en','Ezekiel','A prophet among the deported community.',ARRAY[]::text[],'His narrative setting is Babylon rather than Jerusalem.','To rebuild a framework of meaning for a displaced community.'),
('daniel','zh-CN','但以理','被掳叙事中的宫廷人物。',ARRAY[]::text[],'文本成书年代与叙事年代存在长期讨论。','在异邦宫廷保持自身身份。'),
('daniel','en','Daniel','A court figure in the exile narrative.',ARRAY[]::text[],'The date of composition and the narrative setting are long debated.','To keep his own identity inside a foreign court.'),
('nebuchadnezzar','zh-CN','尼布甲尼撒二世','新巴比伦帝国君主。',ARRAY[]::text[],'外部史料记载充分，是叙事中少数年代可靠的人物。','扩张并巩固帝国控制。'),
('nebuchadnezzar','en','Nebuchadnezzar II','The Neo-Babylonian ruler.',ARRAY[]::text[],'Well documented externally, he is one of the few securely dated figures in the narrative.','To expand and consolidate imperial control.'),
('cyrus','zh-CN','居鲁士二世','波斯君主，归回叙事的政策发布者。',ARRAY[]::text[],'居鲁士圆柱提供外部对照材料。','以宽松政策稳定新征服区域。'),
('cyrus','en','Cyrus II','The Persian ruler whose policy opens the return narrative.',ARRAY[]::text[],'The Cyrus cylinder provides external comparative material.','To stabilise newly conquered regions through permissive policy.'),
('esther','zh-CN','以斯帖','波斯宫廷叙事的主角。',ARRAY['哈大沙']::text[],'叙事以宫廷程序而非军事行动推进。','在无正式权力时改变结果。'),
('esther','en','Esther','The protagonist of the Persian court narrative.',ARRAY['Hadassah']::text[],'The narrative advances through court procedure rather than military action.','To change an outcome while holding no formal power.'),
('mordecai','zh-CN','末底改','以斯帖的养父与宫门官员。',ARRAY[]::text[],'其拒绝行礼成为冲突起点。','在制度内坚持自身立场。'),
('mordecai','en','Mordecai','Esther’s guardian and an official at the palace gate.',ARRAY[]::text[],'His refusal of a gesture starts the conflict.','To hold his position from inside the system.'),
('nehemiah','zh-CN','尼希米','主持耶路撒冷城墙重建的人物。',ARRAY[]::text[],'叙事以第一人称记述工程与政治阻力。','在有限授权下完成公共工程。'),
('nehemiah','en','Nehemiah','The figure who directs the rebuilding of the Jerusalem wall.',ARRAY[]::text[],'The narrative recounts the works and the political resistance in the first person.','To complete a public work under limited authorisation.'),
('joseph-of-nazareth','zh-CN','约瑟（拿撒勒）','马利亚的丈夫，诞生叙事中的人物。',ARRAY[]::text[],'其谱系在福音书叙事中承担王室连接功能。','在意外处境中保护家庭。'),
('joseph-of-nazareth','en','Joseph of Nazareth','Mary’s husband in the birth narrative.',ARRAY[]::text[],'His genealogy carries the royal-line connection in the Gospel narrative.','To protect his household in an unexpected situation.'),
('john-the-baptist','zh-CN','施洗约翰','洗礼叙事的中心人物，外部史料亦有记载。',ARRAY[]::text[],'约瑟夫斯《犹太古史》提到同名人物，是少见的外部对照。','在既有体制之外呼吁改变。'),
('john-the-baptist','en','John the Baptist','The central figure of the baptism narrative, also named in external sources.',ARRAY[]::text[],'Josephus names a figure of this name, a rare external comparison.','To call for change from outside the established institutions.'),
('mary-magdalene','zh-CN','抹大拉的马利亚','福音书叙事中的门徒，复活叙事的首位见证者。',ARRAY[]::text[],'四福音书均记载其在受难与复活段落中的位置。','在群体溃散时继续在场。'),
('mary-magdalene','en','Mary Magdalene','A disciple in the Gospel narrative and the first witness in the resurrection account.',ARRAY[]::text[],'All four Gospels place her in the passion and resurrection sections.','To remain present when the group disperses.'),
('martha','zh-CN','马大','伯大尼家庭叙事中的人物。',ARRAY[]::text[],'与马利亚、拉撒路构成一个家庭单元。','以实际操持维系家庭。'),
('martha','en','Martha','A figure in the Bethany household narrative.',ARRAY[]::text[],'She forms a household unit with Mary and Lazarus.','To hold the household together through practical work.'),
('lazarus','zh-CN','拉撒路','伯大尼叙事中的人物。',ARRAY[]::text[],'其叙事段落在约翰福音中承担转折功能。','作为家庭与公共叙事的连接点。'),
('lazarus','en','Lazarus','A figure in the Bethany narrative.',ARRAY[]::text[],'His section carries a turning-point function in John.','To serve as the link between household and public narrative.'),
('judas-iscariot','zh-CN','加略人犹大','门徒之一，受难叙事中的对立角色。',ARRAY[]::text[],'各福音书对其动机的记述不完全一致。','在文本中动机被不同来源分别归因。'),
('judas-iscariot','en','Judas Iscariot','One of the disciples and the antagonist role in the passion narrative.',ARRAY[]::text[],'The Gospels do not fully agree on his motive.','His motive is attributed differently by different sources.'),
('pontius-pilate','zh-CN','本丢彼拉多','罗马犹太行省长官，受难叙事中的审判者。',ARRAY[]::text[],'该撒利亚出土的彼拉多石碑确认其职衔。','在地方动荡中维持行省秩序。'),
('pontius-pilate','en','Pontius Pilate','The Roman prefect of Judea and the judge in the passion narrative.',ARRAY[]::text[],'The Pilate stone found at Caesarea confirms his title.','To keep provincial order amid local unrest.'),
('herod-the-great','zh-CN','大希律','诞生叙事背景中的犹太地统治者。',ARRAY[]::text[],'其建筑工程有大量考古证据。','以工程与联姻巩固统治合法性。'),
('herod-the-great','en','Herod the Great','The ruler of Judea in the background of the birth narrative.',ARRAY[]::text[],'His building programme is extensively attested archaeologically.','To secure legitimacy through building works and marriage alliance.'),
('john-son-of-zebedee','zh-CN','西庇太的儿子约翰','门徒之一，与雅各为兄弟。',ARRAY[]::text[],'传统上与约翰福音和拔摩岛叙事相关联，此关联仍有讨论。','长期参与群体的建立与扩展。'),
('john-son-of-zebedee','en','John son of Zebedee','A disciple and brother of James.',ARRAY[]::text[],'Traditionally linked to the Fourth Gospel and the Patmos narrative; the linkage remains discussed.','To take a long part in forming and extending the community.'),
('andrew','zh-CN','安得烈','彼得的兄弟，最早被呼召的门徒之一。',ARRAY[]::text[],'伯赛大出身，叙事中多次担任引介角色。','把他人引入群体。'),
('andrew','en','Andrew','Peter’s brother and one of the first disciples called.',ARRAY[]::text[],'From Bethsaida; in the narrative he repeatedly plays an introducing role.','To bring others into the group.'),
('stephen','zh-CN','司提反','早期群体中第一位被处决的成员。',ARRAY[]::text[],'其叙事段落触发耶路撒冷之外的扩散。','公开陈述自身立场。'),
('stephen','en','Stephen','The first member of the early community to be executed.',ARRAY[]::text[],'His section triggers the dispersal beyond Jerusalem.','To state his position publicly.'),
('barnabas','zh-CN','巴拿巴','第一次宣教旅程的同行者。',ARRAY['约瑟']::text[],'在保罗被群体接纳的过程中承担担保角色。','为新加入者提供接纳与背书。'),
('barnabas','en','Barnabas','Paul’s companion on the first missionary journey.',ARRAY['Joseph']::text[],'He vouches for Paul during his acceptance by the community.','To sponsor and vouch for newcomers.'),
('silas','zh-CN','西拉','第二次宣教旅程的同行者。',ARRAY['西尔瓦努']::text[],'在腓立比叙事段落中与保罗同被拘押。','支持行程并承担共同风险。'),
('silas','en','Silas','Paul’s companion on the second missionary journey.',ARRAY['Silvanus']::text[],'He is detained with Paul in the Philippi section.','To support the itinerary and share its risks.'),
('timothy','zh-CN','提摩太','保罗的年轻同工与书信收信人。',ARRAY[]::text[],'跨文化身份在叙事中被明确提及。','在两种文化背景之间承担中介。'),
('timothy','en','Timothy','Paul’s younger colleague and a letter recipient.',ARRAY[]::text[],'His mixed background is explicitly noted in the narrative.','To mediate between two cultural settings.'),
('lydia','zh-CN','吕底亚','腓立比的布商，欧洲叙事中首位记名的接待者。',ARRAY[]::text[],'以独立经济地位提供聚集场所。','以自身资源支持新群体。'),
('lydia','en','Lydia','A cloth merchant in Philippi and the first named host in the European narrative.',ARRAY[]::text[],'Her independent economic standing provides a meeting place.','To support a new community with her own resources.'),
('cornelius','zh-CN','哥尼流','该撒利亚的罗马百夫长。',ARRAY[]::text[],'其叙事段落处理群体边界的扩展。','在既有身份之外寻求参与。'),
('cornelius','en','Cornelius','A Roman centurion at Caesarea.',ARRAY[]::text[],'His section handles the widening of the community’s boundary.','To seek participation from outside the existing identity.'),
('luke','zh-CN','路加','路加福音与使徒行传传统上的作者。',ARRAY[]::text[],'文本中的第一人称复数段落被视为同行记述。','以记述方式保存行程与群体历史。'),
('luke','en','Luke','Traditionally the author of the Gospel of Luke and Acts.',ARRAY[]::text[],'The first-person-plural sections are read as an eyewitness travel account.','To preserve the itinerary and the community’s history in writing.')
) AS v(slug,locale,name,summary,aliases,detail,motivation)
ON c.slug=v.slug AND c.work_id='10000000-0000-4000-8000-000000000005';

-- Birth and death places for the figures whose origin the text states plainly.
UPDATE characters ch SET birth_place_id=l.id
FROM locations l, (VALUES
  ('isaac','canaan-shechem'),('jacob','canaan-shechem'),('joseph-son-of-jacob','canaan-shechem'),
  ('moses','goshen'),('aaron','goshen'),('miriam','goshen'),
  ('samuel','ramah'),('david','bethlehem'),('solomon','jerusalem'),('absalom','hebron'),
  ('boaz','bethlehem'),('jesus','bethlehem'),('paul','tarsus'),
  ('andrew','bethsaida'),('peter','bethsaida'),('barnabas','cyprus-salamis'),('esther','susa')
) AS v(character_slug,location_slug)
WHERE ch.work_id='10000000-0000-4000-8000-000000000005' AND ch.slug=v.character_slug
  AND l.work_id=ch.work_id AND l.slug=v.location_slug;

UPDATE characters ch SET death_place_id=l.id
FROM locations l, (VALUES
  ('moses','mount-nebo'),('aaron','kadesh-barnea'),('saul','mount-gilboa'),('jonathan','mount-gilboa'),
  ('jesus','golgotha-traditional'),('stephen','jerusalem'),('paul','rome'),('john-the-baptist','jerusalem'),
  ('samson','gaza'),('jezebel','samaria-sebaste')
) AS v(character_slug,location_slug)
WHERE ch.work_id='10000000-0000-4000-8000-000000000005' AND ch.slug=v.character_slug
  AND l.work_id=ch.work_id AND l.slug=v.location_slug;

