INSERT INTO character_sources(character_id,source_id)
SELECT c.id,s.id FROM characters c JOIN (VALUES
('noah','Genesis'),('lot','Genesis'),('hagar','Genesis'),('ishmael','Genesis'),('rebekah','Genesis'),
('esau','Genesis'),('rachel','Genesis'),('leah','Genesis'),('joseph-son-of-jacob','Genesis'),
('judah-son-of-jacob','Genesis'),('benjamin','Genesis'),
('miriam','Exodus'),('jethro','Exodus'),('pharaoh-of-the-exodus','Exodus'),
('joshua','Joshua'),('joshua','Numbers'),('caleb','Numbers'),('rahab','Joshua'),
('deborah','Judges'),('barak','Judges'),('gideon','Judges'),('samson','Judges'),('delilah','Judges'),
('ruth','Ruth'),('boaz','Ruth'),
('samuel','Samuel'),('saul','Samuel'),('jonathan','Samuel'),('goliath','Samuel'),('abigail','Samuel'),
('bathsheba','Samuel'),('absalom','Samuel'),('nathan','Samuel'),('joab','Samuel'),
('rehoboam','Kings'),('jeroboam','Kings'),('elijah','Kings'),('elisha','Kings'),('ahab','Kings'),('jezebel','Kings'),
('hezekiah','Kings'),('hezekiah','Isaiah'),('isaiah','Isaiah'),
('jeremiah','Jeremiah'),('ezekiel','Ezekiel'),('daniel','Daniel'),('nebuchadnezzar','Kings'),('cyrus','Ezra'),
('esther','Esther'),('mordecai','Esther'),('nehemiah','Nehemiah'),
('joseph-of-nazareth','Gospel according to Matthew'),('john-the-baptist','Gospel according to Mark'),
('mary-magdalene','Gospel according to John'),('martha','Gospel according to John'),('lazarus','Gospel according to John'),
('judas-iscariot','Gospel according to Matthew'),('pontius-pilate','Gospel according to Mark'),
('herod-the-great','Gospel according to Matthew'),('john-son-of-zebedee','Gospel according to Mark'),
('andrew','Gospel according to John'),('stephen','Acts of the Apostles'),('barnabas','Acts of the Apostles'),
('silas','Acts of the Apostles'),('timothy','Acts of the Apostles'),('lydia','Acts of the Apostles'),
('cornelius','Acts of the Apostles'),('luke','Acts of the Apostles')
) AS v(character_slug,source_title) ON c.slug=v.character_slug AND c.work_id='10000000-0000-4000-8000-000000000005'
JOIN sources s ON s.title=v.source_title AND s.work_id=c.work_id
ON CONFLICT DO NOTHING;

-- Character groups: the middle zoom tier. At low zoom the graph collapses to
-- these; at high zoom it expands to individuals.
