INSERT INTO character_group_translations(group_id,locale,name,summary,status)
SELECT g.id,v.locale::locale_code,v.name,v.summary,'published' FROM character_groups g JOIN (VALUES
('abrahamic-household','zh-CN','亚伯拉罕家族','第一代迁徙家族及其分支。'),('abrahamic-household','en','Abrahamic household','The first migrating household and its branches.'),
('house-of-jacob','zh-CN','雅各家','雅各的妻子与儿子构成的下一代家族。'),('house-of-jacob','en','House of Jacob','The next generation formed by Jacob’s wives and sons.'),
('exodus-leadership','zh-CN','出埃及领导层','出埃及与西奈叙事中的核心领导群体。'),('exodus-leadership','en','Exodus leadership','The core leadership group of the Exodus and Sinai narratives.'),
('conquest-generation','zh-CN','进入迦南一代','旷野末期与定居初期的行动者。'),('conquest-generation','en','Entry generation','The actors of the late wilderness and early settlement period.'),
('judges-circle','zh-CN','士师群体','缺乏中央权力时期的地方性领袖。'),('judges-circle','en','Judges circle','Local leaders during the period without central authority.'),
('house-of-saul','zh-CN','扫罗家','第一个王室及其继承线索。'),('house-of-saul','en','House of Saul','The first royal house and its succession thread.'),
('house-of-david','zh-CN','大卫家','大卫王朝的家庭与宫廷成员。'),('house-of-david','en','House of David','The household and court of the Davidic dynasty.'),
('northern-court','zh-CN','北国宫廷','北国以色列的君主与王后。'),('northern-court','en','Northern court','The kings and queens of the northern kingdom.'),
('prophetic-circle','zh-CN','先知群体','与王权保持距离的先知人物。'),('prophetic-circle','en','Prophetic circle','Prophetic figures who keep a distance from royal power.'),
('exile-court','zh-CN','被掳时期宫廷','巴比伦时期的统治者与流散群体人物。'),('exile-court','en','Exile-period court','Rulers and displaced figures of the Babylonian period.'),
('persian-court','zh-CN','波斯宫廷','归回与以斯帖叙事中的波斯背景人物。'),('persian-court','en','Persian court','The Persian-setting figures of the return and Esther narratives.'),
('nazareth-household','zh-CN','拿撒勒家庭','诞生与成长叙事中的家庭单元。'),('nazareth-household','en','Nazareth household','The household unit of the birth and upbringing narratives.'),
('galilean-disciples','zh-CN','加利利门徒','福音书叙事中的核心门徒群体。'),('galilean-disciples','en','Galilean disciples','The core disciple group of the Gospel narrative.'),
('roman-authorities','zh-CN','罗马与地方当局','行省与附庸统治者。'),('roman-authorities','en','Roman and local authorities','Provincial and client rulers.'),
('bethany-household','zh-CN','伯大尼家庭','耶路撒冷近郊的家庭单元。'),('bethany-household','en','Bethany household','A household unit just outside Jerusalem.'),
('pauline-circle','zh-CN','保罗同工圈','宣教行程中的同行者与接待者。'),('pauline-circle','en','Pauline circle','Companions and hosts along the missionary itinerary.'),
('primeval-figures','zh-CN','起源叙事人物','不放置在历史年代轴上的起源段落人物。'),('primeval-figures','en','Primeval figures','Figures of the origin sections, not placed on the historical axis.'),
('judahite-court','zh-CN','犹大宫廷','南国犹大的君主与同期先知。'),('judahite-court','en','Judahite court','Kings of the southern kingdom and their contemporary prophets.'),
('opposing-powers','zh-CN','对立势力','各时代中与主线叙事对立的外部人物。'),('opposing-powers','en','Opposing powers','Outside figures set against the main narrative line in each era.')
) AS v(slug,locale,name,summary) ON g.slug=v.slug AND g.work_id='10000000-0000-4000-8000-000000000005';

