UPDATE character_groups g SET anchor_character_id=c.id
FROM characters c, (VALUES
  ('abrahamic-household','abraham'),('house-of-jacob','jacob'),('exodus-leadership','moses'),
  ('conquest-generation','joshua'),('judges-circle','samuel'),('house-of-saul','saul'),
  ('house-of-david','david'),('northern-court','ahab'),('prophetic-circle','elijah'),
  ('exile-court','daniel'),('persian-court','esther'),('nazareth-household','jesus'),
  ('galilean-disciples','peter'),('roman-authorities','pontius-pilate'),
  ('bethany-household','martha'),('pauline-circle','paul'),
  ('primeval-figures','noah'),('judahite-court','hezekiah'),('opposing-powers','nebuchadnezzar')
) AS v(group_slug,character_slug)
WHERE g.slug=v.group_slug AND g.work_id='10000000-0000-4000-8000-000000000005'
  AND c.slug=v.character_slug AND c.work_id=g.work_id;

COMMIT;
